# Runs exclusively against this injected mock; no Windows provider, Dolt, SQL, Serve, or secret store is invoked.
. $PSScriptRoot\TS047B-SecureBootstrap.ps1
class MockTs047bHostProvider {
    [hashtable]$State; [System.Collections.Generic.List[string]]$Calls
    MockTs047bHostProvider([hashtable]$state) { $this.State=$state; $this.Calls=[System.Collections.Generic.List[string]]::new() }
    [object] Value([string]$name){ if($this.State.ContainsKey($name)){return $this.State[$name]}; return $null }
    [object] GetHostSnapshot(){ $this.Calls.Add('Host'); return $this.Value('Host') }
    [object] GetIntegrity([string]$p){$this.Calls.Add('Integrity');return $this.Value('Integrity')}
    [object] GetPreviousEffect(){$this.Calls.Add('Previous');return $this.Value('Previous')}
    [object] GetFilesystemState([string]$p){$this.Calls.Add('Filesystem');return $this.Value('Filesystem')}
    [object] GetNetworkState(){$this.Calls.Add('Network');return $this.Value('Network')}
    [object] GetSecretCapability(){$this.Calls.Add('SecretCapability');return $this.Value('SecretCapability')}
    [object] GetSqlCapability(){$this.Calls.Add('SqlCapability');return $this.Value('SqlCapability')}
    [object] GetGrammar(){$this.Calls.Add('Grammar');return $this.Value('Grammar')}
    [byte[]] RandomBytes([int]$n){$this.Calls.Add('Random');if($this.Value('RandomFail')){return [byte[]]::new(0)};return [byte[]]@(1)*$n}
    [void] CreateLabRoot([string]$p){$this.Calls.Add('CreateRoot')}
    [void] StoreProtectedSecret([string]$n,[byte[]]$s,[string]$p){$this.Calls.Add("Store:$n");if($this.Value('DpapiFail')){throw 'DPAPI_WRITE_FAILED'}}
    [void] WriteServerConfig([string]$p){$this.Calls.Add('Config')}
    [void] StartLoopbackSql([string]$p){$this.Calls.Add('Start');if($this.Value('StartFail')){throw 'PROCESS_CRASH'}}
    [object] OpenSql([string]$u,[byte[]]$p){$this.Calls.Add("Open:$u");if($this.Value('OpenFail')){throw 'AUTH_FAILED'};return [pscustomobject]@{User=$u}}
    [void] ExecuteSql([object]$c,[string]$s){$this.Calls.Add('Sql');if($this.Value('SqlFail')){throw 'SQL_FAILURE'}}
    [void] ExecuteSqlSecret([object]$c,[string]$s,[byte[]]$secret){$this.Calls.Add('SqlSecret');if($this.Value('SqlFail')){throw 'SQL_FAILURE'}}
    [void] CloseSql([object]$c){$this.Calls.Add('Close')}
    [object] VerifyPostconditions(){$this.Calls.Add('Post');return $this.Value('Post')}
}
function New-GoodState { @{ Host=[pscustomobject]@{IsWindows=$true;HostName='DESKTOP-DJLBEQH';OwnerDevice='40cc0b10-fa7b-4a6a-98cf-1c94f93791b2';DoltVersion='dolt version 2.2.0';BeadsVersion='bd 1.3.1';TailnetRunning=$true;ApprovedPeerOnline=$true}; Integrity=[pscustomobject]@{SourceSha256='A'*64;ParserOk=$true}; Previous=[pscustomobject]@{State='NONE'}; Filesystem=[pscustomobject]@{Exists=$false;Reparse=$false;Collision=$false;RestrictedAcl=$true;ProductPath=$false}; Network=[pscustomobject]@{PortVacant=$true;SqlListener=$false;Serve=$false;Funnel=$false}; SecretCapability=[pscustomobject]@{Csprng=$true;Dpapi=$true;RestrictedAcl=$true}; SqlCapability=[pscustomobject]@{SecureConnector=$true}; Grammar=[pscustomobject]@{CreateUser=$true;DropUser=$true;Grant=$true;VerifiedPinnedDolt=$true}; Post=[pscustomobject]@{RootPasswordlessDenied=$true;AdminRecovery=$true;WriterScoped=$true;ReaderMutationDenied=$true;WrongPasswordDenied=$true;LoopbackOnly=$true;ServeDisabled=$true} } }
$script:passed=0; $script:failed=0
function Assert-Test([string]$name,[scriptblock]$body){try{&$body;$script:passed++;"PASS $name"}catch{$script:failed++;"FAIL $name :: $($_.Exception.Message)"}}
function Assert-Blocked([string]$expected,[MockTs047bHostProvider]$p){try{Invoke-TS047BSecureBootstrap -Mode Validate -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64)|Out-Null;throw 'expected block'}catch{if($_.Exception.Message -ne "BLOCKED_$expected"){throw $_}};if($p.Calls -contains 'Start'){throw 'effect after block'}}
Assert-Test 'validate passes with no effects' {$p=[MockTs047bHostProvider]::new((New-GoodState));$r=Invoke-TS047BSecureBootstrap -Mode Validate -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64);if($r.Status -ne 'STATIC_CANDIDATE_FOR_INDEPENDENT_REVIEW' -or $p.Calls -contains 'Start'){throw 'bad validate'}}
@(@('wrong host','Host',{param($s)$s.Host.HostName='OTHER'},'HOST_OR_OWNER_MISMATCH'),@('wrong owner','Host',{param($s)$s.Host.OwnerDevice='OTHER'},'HOST_OR_OWNER_MISMATCH'),@('bad binary','Host',{param($s)$s.Host.DoltVersion='2.1.0'},'PINNED_BINARY_MISMATCH'),@('offline peer','Host',{param($s)$s.Host.ApprovedPeerOnline=$false},'TAILNET_PEER_UNVERIFIED'),@('bad parser','Integrity',{param($s)$s.Integrity.ParserOk=$false},'INTEGRITY_OR_PARSER_FAILURE'),@('bad hash','Integrity',{param($s)$s.Integrity.SourceSha256='B'*64},'INTEGRITY_OR_PARSER_FAILURE'),@('prior unknown','Previous',{param($s)$s.Previous.State='UNKNOWN'},'PRIOR_EFFECT_RECONCILIATION_REQUIRED'),@('existing root','Filesystem',{param($s)$s.Filesystem.Exists=$true},'LAB_ROOT_OR_ACL_UNSAFE'),@('reparse root','Filesystem',{param($s)$s.Filesystem.Reparse=$true},'LAB_ROOT_OR_ACL_UNSAFE'),@('bad ACL','Filesystem',{param($s)$s.Filesystem.RestrictedAcl=$false},'LAB_ROOT_OR_ACL_UNSAFE'),@('product path','Filesystem',{param($s)$s.Filesystem.ProductPath=$true},'LAB_ROOT_OR_ACL_UNSAFE'),@('port occupied','Network',{param($s)$s.Network.PortVacant=$false},'NETWORK_EXPOSURE_OR_PORT_UNSAFE'),@('serve enabled','Network',{param($s)$s.Network.Serve=$true},'NETWORK_EXPOSURE_OR_PORT_UNSAFE'),@('funnel enabled','Network',{param($s)$s.Network.Funnel=$true},'NETWORK_EXPOSURE_OR_PORT_UNSAFE'),@('DPAPI unavailable','SecretCapability',{param($s)$s.SecretCapability.Dpapi=$false},'SECRET_PROTECTION_UNAVAILABLE'),@('connector missing','SqlCapability',{param($s)$s.SqlCapability.SecureConnector=$false},'SECURE_SQL_CLIENT_UNAVAILABLE'),@('grammar missing','Grammar',{param($s)$s.Grammar.Grant=$false},'PINNED_SQL_GRAMMAR_UNVERIFIED')) | ForEach-Object {$case=$_;Assert-Test $case[0] {$s=New-GoodState;&$case[2] $s;$p=[MockTs047bHostProvider]::new($s);Assert-Blocked $case[3] $p}}
Assert-Test 'apply requires future distinct attempt' {$p=[MockTs047bHostProvider]::new((New-GoodState));try{Invoke-TS047BSecureBootstrap -Mode Apply -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64) -FutureExecutionAttempt 'TS-BEADS-047B-IR002-PUBLIC-BUILD-20261101-001' -EffectApproval @{ExplicitEffectGrant=$true;SourceSha256='A'*64}|Out-Null;throw 'expected'}catch{if($_.Exception.Message -ne 'BLOCKED_DISTINCT_FUTURE_ATTEMPT_REQUIRED'){throw $_}}}
Assert-Test 'apply requires explicit grant' {$p=[MockTs047bHostProvider]::new((New-GoodState));try{Invoke-TS047BSecureBootstrap -Mode Apply -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64) -FutureExecutionAttempt 'FUTURE-001' -EffectApproval @{}|Out-Null;throw 'expected'}catch{if($_.Exception.Message -ne 'BLOCKED_EXPLICIT_EFFECT_GRANT_REQUIRED'){throw $_}}}
Assert-Test 'CSPRNG failure blocks before root creation' {$s=New-GoodState;$s.RandomFail=$true;$p=[MockTs047bHostProvider]::new($s);try{Invoke-TS047BSecureBootstrap -Mode Apply -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64) -FutureExecutionAttempt 'FUTURE-001' -EffectApproval @{ExplicitEffectGrant=$true;SourceSha256='A'*64}|Out-Null;throw 'expected'}catch{if($_.Exception.Message -ne 'BLOCKED_CSPRNG_FAILED'){throw $_}};if($p.Calls -contains 'CreateRoot'){throw 'downstream effect'}}
Assert-Test 'DPAPI failure preserves no SQL start' {$s=New-GoodState;$s.DpapiFail=$true;$p=[MockTs047bHostProvider]::new($s);$r=Invoke-TS047BSecureBootstrap -Mode Apply -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64) -FutureExecutionAttempt 'FUTURE-001' -EffectApproval @{ExplicitEffectGrant=$true;SourceSha256='A'*64};if($r.Status -ne 'UNKNOWN_OR_PARTIAL_PRESERVE_STATE' -or $p.Calls -contains 'Start'){throw 'incorrect failure fence'}}
Assert-Test 'process crash preserves state and bans retry' {$s=New-GoodState;$s.StartFail=$true;$p=[MockTs047bHostProvider]::new($s);$r=Invoke-TS047BSecureBootstrap -Mode Apply -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64) -FutureExecutionAttempt 'FUTURE-001' -EffectApproval @{ExplicitEffectGrant=$true;SourceSha256='A'*64};if($r.Status -ne 'UNKNOWN_OR_PARTIAL_PRESERVE_STATE' -or $r.Retry -ne 'FORBIDDEN'){throw 'missing fence'}}
Assert-Test 'root, writer, reader and auth postconditions run through mock SQL' {$p=[MockTs047bHostProvider]::new((New-GoodState));$r=Invoke-TS047BSecureBootstrap -Mode Apply -Provider $p -SourcePath $PSCommandPath -ExpectedSourceSha256 ('A'*64) -FutureExecutionAttempt 'FUTURE-001' -EffectApproval @{ExplicitEffectGrant=$true;SourceSha256='A'*64};if($r.Status -ne 'FUTURE_APPLY_PASS' -or $p.Calls -notcontains 'Post'){throw 'missing mocked authorization'}}
